{
  "findings": [
    {
      "check_id": "CKV_GCP_26",
      "title": "VPC flow logging is not enabled",
      "resource": "google_compute_subnetwork.data_subnet",
      "severity": "MEDIUM",
      "explanation": "The data subnet does not enable VPC flow logs, limiting visibility into network traffic and reducing the ability to investigate suspicious access to the Cloud SQL data tier."
    }
  ],
  "patched_code": "resource "google_compute_subnetwork" "data_subnet" {
  name                     = "insurance-claims-processing-platform-subnet-data"
  ip_cidr_range            = "10.0.3.0/24"
  region                   = var.region
  network                  = google_compute_network.claims_vpc.id
  description              = "Data subnet for Cloud SQL database"
  private_ip_google_access = true

  log_config {
    aggregation_interval = "INTERVAL_5_SEC"
    flow_sampling        = 0.5
    metadata             = "INCLUDE_ALL_METADATA"
  }
}
",
  "fix_summary": "Enabled VPC flow logging on the data subnet to provide network traffic visibility and support security monitoring and incident investigation."
}
